        valid = True
        for c1 in colors1:
            if c1 not in mapping:
                for c2 in colors2:
                    if c2 not in mapping.values():
                        mapping[c1] = c2
                        break
                else:
                    valid = False
                    break
            if not valid:
                break

        if not valid:
            continue

        # Check if transformation works
        def apply_transform(b):
            result = [[mapping.get(c, c) for c in row] for row in b]
            return result

        if [apply_transform(temp)] == [apply_transform(block2)]:
